// ── Compression types ──

export interface CompressionStats {
  current_tokens: number;
  token_limit: number;
  message_count: number;
  compression_ratio: number;
  protected_message_count?: number;
  runtime_recovery_active?: boolean;
  needs_compression: boolean;
}

export interface CompressResponse {
  success: boolean;
  messages_before: number;
  messages_after: number;
  tokens_saved: number;
  message: string;
  tokens_before?: number;
  tokens_after?: number;
  checkpoint?: {
    strategy: string;
    protected_count: number;
    compression_duration_ms: number;
  } | null;
}

// ── Conversation persistence types ──

export interface SavedMessage {
  message_id?: string;
  role: string;
  created_at: string;
  content: string | null;
  internal_agent?: boolean;
  agent_input?: AgentCommunicationInput['payload'];
  assistant_blocks?: AssistantBlockView[];
  final_answer_confirmed?: boolean;
  /** 后端既有 publication 校验得到的原 Settled 坐标与精确候选块。 */
  execution_status?: NativeExecutionStatus;
  final_answer_source?: NativeFinalAnswerSource;
  tool_calls?: {
    provider_source?: ProviderOutputSource | null;
    id: string;
    type: string;
    function: { name: string; arguments: string };
  }[];
  execution_steps?: { type: string; index?: number; call_id?: string }[];
  tool_result?: string | null;
  /** Inline attachments retain their data URL. Artifact-backed text keeps
   * metadata only, so it can render after reload without duplicating content. */
  attachments?: {
    name: string;
    mime_type: string;
    url: string;
    size: number;
    source?: Attachment['source'];
  }[];
}

export interface ConversationRecord {
  id: string;
  conversation_id: string;
  title: string;
  messages: SavedMessage[];
  created_at: string;
  updated_at: string;
}

export interface ConversationListItem {
  id: number;
  conversation_id: string;
  title: string | null;
  message_count: number;
  created_at: string;
  updated_at: string;
  archived?: boolean;
  side_conversation?: import('../generated').SideConversationEntry | null;
}

